import{Vector2 as e}from"@papit/vector";function f(r,c,o,n){let t=e.subtract(c,r),V=e.subtract(n,o),s=e.cross(t,V);if(s===0)return!1;let a=e.subtract(o,r),u=e.cross(a,V)/s,l=e.cross(a,t)/s;return{x:new e(r).x+u*t.x,y:new e(r).y+u*t.y,t:u,u:l}}function m(r,c,o,n){let t=f(r,c,o,n);return t===!1?!1:t.t>=0&&t.t<=1&&t.u>=0&&t.u<=1?t:!1}export{f as LineIntersection,m as SegmentIntersection};
